def choose_move(observation):
    # Defensive defaults
    grid = observation.get('grid') if isinstance(observation, dict) else None
    player_pos = observation.get('player_pos') if isinstance(observation, dict) else None
    targets = observation.get('targets') if isinstance(observation, dict) else None
    enemies = observation.get('enemies') if isinstance(observation, dict) else None
    own_resources = observation.get('resources') if isinstance(observation, dict) else None
    territory = observation.get('territory') if isinstance(observation, dict) else None

    # Fallback to current position if available
    if isinstance(player_pos, (list, tuple)) and len(player_pos) >= 2:
        x, y = int(player_pos[0]), int(player_pos[1])
    else:
        x, y = 0, 0

    # Helper: safe move check (no walls knowledge; rely on grid if present)
    def can_move(nx, ny):
        if grid is None:
            return True
        if not isinstance(grid, (list, tuple)):
            return True
        if ny < 0 or nx < 0:
            return False
        if ny >= len(grid) or nx >= len(grid[ny]):
            return False
        cell = grid[ny][nx]
        # assume 0 means empty, 1 obstacle
        return cell == 0 if isinstance(cell, int) else True

    # Prefer simple: move toward closest interesting objective when available
    best_dx, best_dy = 0, 0

    # Determine targets by priority: resources -> enemies (pursuit) -> territory
    # Try to approach nearest resource if exists
    if isinstance(own_resources, (list, tuple)):
        try:
            best = None
            for r in own_resources:
                if isinstance(r, (list, tuple)) and len(r) >= 2:
                    rx, ry = int(r[0]), int(r[1])
                    dist = abs(rx - x) + abs(ry - y)
                    if best is None or dist < best[0]:
                        best = (dist, rx, ry)
            if best is not None:
                tx, ty = best[1], best[2]
                dx = 0 if tx == x else (1 if tx > x else -1)
                dy = 0 if ty == y else (1 if ty > y else -1)
                if can_move(x + dx, y + dy):
                    return [dx, dy]
        except Exception:
            pass

    # If no resources or not reachable, pursue closest enemy if present
    if isinstance(enemies, (list, tuple)):
        try:
            best = None
            for e in enemies:
                if isinstance(e, (list, tuple)) and len(e) >= 2:
                    ex, ey = int(e[0]), int(e[1])
                    dist = abs(ex - x) + abs(ey - y)
                    if best is None or dist < best[0]:
                        best = (dist, ex, ey)
            if best is not None:
                tx, ty = best[1], best[2]
                dx = 0 if tx == x else (1 if tx > x else -1)
                dy = 0 if ty == y else (1 if ty > y else -1)
                if can_move(x + dx, y + dy):
                    return [dx, dy]
        except Exception:
            pass

    # Territory control: move toward nearest unclaimed/low-control cell if data provided
    if isinstance(territory, (list, tuple)):
        try:
            best = None
            for t in territory:
                if isinstance(t, (list, tuple)) and len(t) >= 2:
                    tx, ty = int(t[0]), int(t[1])
                    dist = abs(tx - x) + abs(ty - y)
                    if best is None or dist < best[0]:
                        best = (dist, tx, ty)
            if best is not None:
                tx, ty = best[1], best[2]
                dx = 0 if tx == x else (1 if tx > x else -1)
                dy = 0 if ty == y else (1 if ty > y else -1)
                if can_move(x + dx, y + dy):
                    return [dx, dy]
        except Exception:
            pass

    # Fallback: stay or step in a safe direction
    for dx, dy in ((0,0), (1,0), (-1,0), (0,1), (0,-1)):
        nx, ny = x + dx, y + dy
        if dx == 0 and dy == 0:
            return [0, 0]
        if can_move(nx, ny):
            return [dx, dy]

    # If all else fails, no-op
    return [0, 0]

